<?php if($user['role']==='super_admin'):?><section class="card"><h2>Administrator profile</h2><p class="hint">Update your display name and sign-in username. Super Admin access and your existing password stay the same.</p><form method="post" class="form-grid core-form"><?php ftoken();?><input type="hidden" name="action" value="save_admin_identity"><label>Display name<input name="name" maxlength="150" value="<?=h(($error&&($_POST['action']??'')==='save_admin_identity')?($_POST['name']??''):$user['name'])?>" required></label><label>Username<input name="username" maxlength="190" value="<?=h(($error&&($_POST['action']??'')==='save_admin_identity')?($_POST['username']??''):($user['username']??''))?>" required></label><div class="full"><button class="button primary">Save administrator profile</button></div></form></section><?php endif;?>
<section class="card"><div class="card-heading"><h2>Your sign-in details</h2></div><dl class="details"><div><dt>Name</dt><dd><?=h($user['name'])?></dd></div><div><dt>Username</dt><dd><?=h($user['username']??'Not set')?></dd></div><div><dt>Work email</dt><dd><?=h($user['email']?:'Not set')?></dd></div></dl><p class="hint">Use your username or registered work email to sign in.</p></section><section class="card"><div class="card-heading"><h2>Change password</h2></div><?php if(!empty($user['must_change_password'])):?><div class="alert success">Choose a new password before continuing to your workspace.</div><?php endif;?><form method="post"><?php ftoken();?><input type="hidden" name="action" value="change_password"><div class="form-grid"><label class="full">Current password<input type="password" name="current_password" autocomplete="current-password" required></label><label>New password<input type="password" name="new_password" minlength="12" maxlength="72" autocomplete="new-password" required></label><label>Confirm new password<input type="password" name="confirm_password" minlength="12" maxlength="72" autocomplete="new-password" required></label></div><p class="hint">Use 12–72 characters. Changing your password signs out your other sessions.</p><div class="form-actions"><button class="button primary">Change password</button></div></form></section>
